import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
FIX = os.path.join(HERE, "fixtures") + os.sep
REPO = os.path.dirname(os.path.dirname(HERE))
sys.path.insert(0, HERE)
import sys, re
from shots import run, BASE, OUT

results = []
def check(name, cond, detail=""):
    results.append((name, bool(cond), str(detail)))
def data(page, expr):
    return page.evaluate("(() => { const s = JSON.parse(localStorage.getItem('cod.data')).state; const db = s.db; const day = s.day; return " + expr + "; })()")
def as_role(page, role):
    page.get_by_role("button", name="Account menu").click()
    page.get_by_role("menuitem", name=role).click()
    page.wait_for_timeout(350)
def toast(page):
    return page.locator("[aria-live=polite]").last.inner_text()

def steps(page, ctx):
    page.goto(BASE + "/"); page.wait_for_url("**/sign-in")
    page.fill("#username", "demo"); page.fill("#password", "demo"); page.click("button[type=submit]")
    page.wait_for_url("**/who"); page.get_by_role("button", name="Managing director").click(); page.wait_for_url("**/dashboard")
    main = page.locator("main")

    # 1. Person box: email fits
    page.goto(BASE + "/people?person=p-sm4"); page.wait_for_selector("dialog[open]")
    dlg = page.locator("dialog[open]")
    over = page.evaluate("""() => { const d = document.querySelector('dialog[open]'); const a = d.querySelector('a[href^="mailto:"]'); const dl = a.closest('dl'); const r = a.getBoundingClientRect(), b = dl.getBoundingClientRect(); return [Math.round(r.right), Math.round(b.right), d.scrollWidth > d.clientWidth]; }""")
    check("Person box: the email stays inside its column and does not run under the tickets", over[0] <= over[1] + 1 and not over[2], over)
    check("Person box: phone and email are links to ring or write", dlg.locator('a[href="tel:0852417611"]').count() + dlg.locator('a[href^="tel:"]').count() >= 1 and dlg.locator('a[href="mailto:darragh.lenihan@abcconstruction.example"]').count() == 1)
    check("Person box: shows the access level with a link to change it", "Access level" in dlg.inner_text() and "Site manager" in dlg.inner_text() and dlg.get_by_role("link", name="Change").count() == 1)
    page.screenshot(path=f"{OUT}/80-person-box.png")
    page.set_viewport_size({"width": 390, "height": 844}); page.wait_for_timeout(200)
    over = page.evaluate("""() => { const d = document.querySelector('dialog[open]'); const a = d.querySelector('a[href^="mailto:"]'); const r = a.getBoundingClientRect(); return [Math.round(r.right), window.innerWidth]; }""")
    check("Person box: email also fits at phone width", over[0] <= over[1], over)
    page.screenshot(path=f"{OUT}/81-person-box-mobile.png")
    page.set_viewport_size({"width": 1440, "height": 900})

    # 2. Photos: camera or file, real picture, open and download
    page.goto(BASE + "/projects/C720?tab=photos"); page.wait_for_timeout(400)
    if page.get_by_role("button", name="Add a photo").count() == 0:
        page.get_by_role("tab", name="Photos").click(); page.wait_for_timeout(300)
    n0 = page.locator("main ul li").count()
    page.get_by_role("button", name="Add a photo").click()
    dlg = page.locator("dialog[open]")
    check("Photos: both a camera button and a file button are offered", dlg.get_by_role("button", name="Take a photo", exact=True).count() == 1 and dlg.get_by_role("button", name="Choose a file", exact=True).count() == 1)
    cam = dlg.get_by_label("Take a photo with the camera")
    check("Photos: the camera input asks the device for its rear camera", cam.get_attribute("capture") == "environment" and cam.get_attribute("accept") == "image/*")
    check("Photos: cannot be added without a picture", dlg.get_by_role("button", name="Add photo").is_disabled())
    dlg.get_by_label("Choose a photo from this device").set_input_files(FIX + "notes.txt"); page.wait_for_timeout(500)
    check("Photos: a file that is not a picture is refused in plain words", "not a picture" in dlg.inner_text(), dlg.inner_text()[-200:])
    dlg.get_by_label("Choose a photo from this device").set_input_files(FIX + "site-photo.jpg"); page.wait_for_timeout(700)
    check("Photos: the chosen picture is previewed", dlg.locator("img").count() == 1 and "site-photo.jpg" in dlg.inner_text())
    dlg.get_by_label("Caption").fill("North elevation, repointing under way")
    dlg.get_by_label("Stage").select_option("During")
    page.screenshot(path=f"{OUT}/82-add-photo.png")
    dlg.get_by_role("button", name="Add photo").click(); page.wait_for_timeout(400)
    f = data(page, "(() => { const f = db.files.find(f => f.caption==='North elevation, repointing under way'); return [f.dataUrl.slice(0,23), f.sizeKb, f.addedBy, f.stage] })()")
    check("Photos: the real picture is saved, shrunk to a sensible size", f[0] == "data:image/jpeg;base64," and 5 < f[1] < 600 and f[2] == "Aidan King" and f[3] == "During", f)
    check("Photos: it appears first in the grid as a real image", page.locator("main ul li").count() == n0 + 1 and page.locator("main ul li").first.locator("img").count() == 1)
    page.locator("main ul li").first.locator("button").click(); page.wait_for_timeout(300)
    dlg = page.locator("dialog[open]")
    dims = dlg.locator("img").evaluate("i => [i.naturalWidth, i.naturalHeight]")
    link = dlg.get_by_role("link", name="Download")
    check("Photos: opens large, at most 1280 pixels on its long side", dims == [1280, 960], dims)
    with page.expect_download() as dl:
        link.click()
    check("Photos: downloads as a file named after the caption", dl.value.suggested_filename == "North elevation, repointing under way.jpg", dl.value.suggested_filename)
    page.screenshot(path=f"{OUT}/83-photo-open.png")
    page.reload(); page.wait_for_timeout(500)
    check("Photos: the picture survives a refresh", data(page, "db.files.filter(f => f.dataUrl).length") == 1 and page.locator("main ul li img").count() == 1)

    # 4. Tickets: proof
    # In Compliance since 18 Nov: the tickets that need attention, then everything.
    page.goto(BASE + "/compliance?area=personnel"); page.wait_for_selector("table")
    n_att = page.locator("tbody tr").count()
    row = page.locator("tbody tr", has_text="Thiago Barbosa")
    row.get_by_role("button", name="Renew").click()
    page.locator("dialog[open]").get_by_role("button", name="Save renewal").click(); page.wait_for_timeout(300)
    check("Tickets: a renewal saved with no proof stays on the list as Proof needed", page.locator("tbody tr").count() == n_att and "Proof needed" in row.inner_text() and "In date" in row.inner_text(), row.inner_text())
    proof_tile = page.locator("dl[aria-label='Compliance figures'] button", has_text="Proof needed").inner_text()
    check("Tickets: the figures count what is waiting on proof", "3" in proof_tile, proof_tile)
    page.goto(BASE + "/compliance/personnel?view=list&person=p-108"); page.wait_for_selector("table")
    row = page.locator("tbody tr", has_text="Manual handling")
    row.get_by_role("button", name="Add proof").click()
    dlg = page.locator("dialog[open]")
    check("Tickets: proof cannot be attached without a file", dlg.get_by_role("button", name="Attach proof").is_disabled())
    dlg.get_by_label("Choose a proof from this device").set_input_files(FIX + "notes.txt"); page.wait_for_timeout(400)
    check("Tickets: only a photo or a PDF is accepted as proof", "photo of the card or a PDF" in dlg.inner_text())
    dlg.get_by_label("Choose a proof from this device").set_input_files(FIX + "cert.pdf"); page.wait_for_timeout(400)
    dlg.get_by_role("button", name="Attach proof").click(); page.wait_for_timeout(300)
    page.goto(BASE + "/compliance?area=personnel"); page.wait_for_selector("table")
    check("Tickets: once proof is attached the ticket leaves the list", page.locator("tbody tr", has_text="Thiago Barbosa").count() == 0 and page.locator("tbody tr").count() == n_att - 1)
    page.get_by_role("tab", name=re.compile("^Everything")).click(); page.wait_for_timeout(300)
    row = page.locator("tbody tr", has_text="Thiago Barbosa").filter(has_text="Manual handling")
    row.get_by_role("button", name="View proof").click(); page.wait_for_timeout(250)
    dlg = page.locator("dialog[open]")
    check("Tickets: the proof opens with who attached it and a download", "cert.pdf" in dlg.inner_text() and "Attached by Aidan King" in dlg.inner_text() and dlg.get_by_role("link", name="Download").get_attribute("download") == "cert.pdf")
    page.screenshot(path=f"{OUT}/84-proof.png")
    dlg.get_by_role("button", name="Close").click()
    check("Tickets: tickets from before the system say On paper file and offer Add proof", page.locator("tbody tr", has_text="On paper file").count() > 100 and page.locator("tbody tr", has_text="On paper file").filter(has_text="In date").first.get_by_role("button", name="Add proof").count() == 1, page.locator("tbody tr", has_text="On paper file").count())
    page.goto(BASE + "/people?person=p-110"); page.wait_for_timeout(300)

    # 6 and 7. Week ahead: one grid, Not placed beside it (17 Nov: sites by days, drag and drop)
    page.goto(BASE + "/schedule"); page.wait_for_selector("table")
    grid = page.get_by_role("table", name="Week ahead by site and day")
    side = page.get_by_role("complementary", name="Not placed this week")
    free_all = ["Adrian Stoica", "Rafael Mendonça", "Piotr Zieliński", "Krzysztof Nowicki", "Darius Kazlauskas"]
    kn = [t for t in side.locator("li").all_inner_texts() if t.startswith("Krzysztof")]
    check("Not placed: someone with only a half day planned on Tuesday shows Tuesday as still open", kn and "Tue to Fri" in kn[0], kn)
    listed = [t.split("\n")[0] for t in side.locator("li").all_inner_texts()]
    check("Week ahead: the Not placed list shows exactly the operatives with a free day", sorted(listed) == sorted(free_all) and len(listed) > 0, (listed, free_all))
    check("Week ahead: the list says how many and who is free all week, and that names can be dragged", f"Not placed {len(listed)}" in side.inner_text().replace("\n", " ") and "All week" in side.inner_text() and "Drag a name" in side.inner_text(), side.inner_text()[:200])
    page.screenshot(path=f"{OUT}/85-week-ahead-not-placed.png")
    days = data(page, "(() => { const out=[]; let d=new Date(day+'T12:00:00Z'); do { d.setUTCDate(d.getUTCDate()+1) } while (d.getUTCDay()!==1); for (let i=0;i<5;i++){ out.push(d.toISOString().slice(0,10)); d.setUTCDate(d.getUTCDate()+1) } return out })()")
    cell = lambda code, i: grid.locator(f"td[data-cell='{code} {days[i]}']")
    chip = lambda code, i, name: cell(code, i).get_by_role("button", name=f"{name}: contact details and options")
    def drag(src, dst, done):
        for n in range(4):  # the first drag after a dialog closes does not start in the test browser
            src.drag_to(dst); page.wait_for_timeout(300)
            if done(): return
            pass
    # Drag from Not placed: Rafael, free all week, onto C719 Monday
    rafael = data(page, "db.people.find(p=>p.name==='Rafael Mendonça').id")
    on = lambda pid, code, i: data(page, f"db.plan.some(p => p.personId==='{pid}' && p.projectId==='pr-{code}' && p.date==='{days[i]}')")
    drag(side.get_by_role("button", name=re.compile("^Rafael Mendonça")), cell("C719", 0), lambda: on(rafael, "C719", 0))
    check("Drag: a name from Not placed dropped on a site and day plans them for that day only", on(rafael, "C719", 0) and not on(rafael, "C719", 1) and chip("C719", 0, "Rafael Mendonça").count() == 1)
    # 17 Nov (Oisin): the first time someone goes on a site in the week, ask about the rest of it
    ask = page.get_by_role("group", name="Here for the rest of the week?")
    check("Rest of the week: asked after someone's first day on a site, with Yes and No", ask.count() == 1 and "Rafael Mendonça is on C719 on Mon" in ask.inner_text() and "Tue to Fri" in ask.inner_text() and ask.get_by_role("button", name="Yes").count() == 1 and ask.get_by_role("button", name="No").count() == 1, ask.inner_text() if ask.count() else "")
    ask.get_by_role("button", name="No").click(); page.wait_for_timeout(200)
    check("Rest of the week: No leaves just that day", ask.count() == 0 and not on(rafael, "C719", 1))
    big0 = cell("C719", 1).bounding_box()["height"]
    check("Drag: the cell grows a line for the person added", cell("C719", 0).locator("button[aria-label$='contact details and options']").count() == cell("C719", 1).locator("button[aria-label$='contact details and options']").count() + 1)
    # The Add button: anyone free that day, one tap
    cell("C719", 1).get_by_role("button", name=re.compile("^Add someone")).click(); page.wait_for_timeout(250)
    dlg = page.locator("dialog[open]").last
    free_names = dlg.get_by_role("list", name="Free that day").locator("li").all_inner_texts()
    check("Add: lists only people free that day", len(free_names) >= 4 and any(t.startswith("Rafael Mendonça") for t in free_names) and not any(t.startswith("Kevin Shortall") for t in free_names), free_names)
    dlg.get_by_role("button", name=re.compile("^Rafael Mendonça")).click(); page.wait_for_timeout(250)
    check("Add: tapping a name puts them on that day, with no question the second time", on(rafael, "C719", 1) and page.locator("dialog[open]").count() == 0 and ask.count() == 0)
    # Florin is on C723 all week: dropping him on C724 asks first; Put on both double books
    florin = data(page, "db.people.find(p=>p.name==='Florin Dobre').id")
    drag(chip("C723", 0, "Florin Dobre"), cell("C724", 2), lambda: page.locator("dialog[open]").count() > 0)
    dlg = page.locator("dialog[open]").last
    check("Busy: dropping Florin, who is on C723, asks before anything is planned", "Florin Dobre is on C723 that day" in dlg.inner_text() and not on(florin, "C724", 2), dlg.inner_text()[:200])
    page.screenshot(path=f"{OUT}/86-drop-busy.png")
    dlg.get_by_role("button", name="Put on both").click(); page.wait_for_timeout(300)
    check("Busy: Put on both shows the clash in red on both sites", "double booking" in main.inner_text() and chip("C724", 2, "Florin Dobre").evaluate("b => b.className.includes('bg-bad-soft')") and chip("C723", 2, "Florin Dobre").inner_text().endswith("+C724"))
    chip("C724", 2, "Florin Dobre").click(); page.wait_for_timeout(250)
    dlg = page.locator("dialog[open]")
    check("Week ahead: clicking a name opens a box with phone and email to ring or write", dlg.locator("a[href^='tel:']").count() == 1 and dlg.locator("a[href='mailto:florin.dobre@abcconstruction.example']").count() == 1, dlg.inner_text()[:200])
    check("Week ahead: the box shows his week with both sites on the clash day", dlg.locator("li", has_text=" + ").count() == 1, dlg.inner_text())
    page.screenshot(path=f"{OUT}/87-person-week-box.png")
    dlg.get_by_role("button", name="Take off C724").click(); page.wait_for_timeout(300)
    st = data(page, f"[db.plan.filter(p=>p.personId==='{florin}'&&p.projectId==='pr-C724').length, db.assignments.filter(a=>a.personId==='{florin}'&&a.projectId==='pr-C724').length, db.plan.filter(p=>p.personId==='{florin}'&&p.projectId==='pr-C723'&&p.date>day).length]")
    check("Week ahead: Take off removes him from C724 and leaves C723 alone", chip("C724", 2, "Florin Dobre").count() == 0 and st[0] == 0 and st[1] == 0 and st[2] >= 5, st)
    check("Week ahead: and the clash he caused is gone", "Florin Dobre is on" not in main.inner_text())
    # Moving on the same day: Florin from C723 Thursday straight to C724 Thursday, no question asked
    drag(chip("C723", 3, "Florin Dobre"), cell("C724", 3), lambda: on(florin, "C724", 3))
    check("Move: dragging a name to another site on the same day moves them, no double booking", on(florin, "C724", 3) and not on(florin, "C723", 3) and on(florin, "C723", 4) and "Florin Dobre is on C723 and" not in main.inner_text(), [on(florin, "C724", 3), on(florin, "C723", 3), on(florin, "C723", 4), main.inner_text()[:300]])
    check("Rest of the week: after a move it offers to move the rest of the week across", ask.count() == 1 and "Florin Dobre is on C724 on Thu" in ask.inner_text() and "moved from C723" in ask.inner_text(), ask.inner_text() if ask.count() else "")
    ask.get_by_role("button", name="Yes").click(); page.wait_for_timeout(300)
    check("Rest of the week: Yes moves Friday too, with no double booking", on(florin, "C724", 4) and not on(florin, "C723", 4) and ask.count() == 0 and "Florin Dobre is on C723 and" not in main.inner_text() and "rest of the week" in page.locator("[aria-live=polite]").last.inner_text())
    # Yes from Not placed: Piotr, free all week, dropped on Tuesday goes on Wednesday to Friday as well
    piotr = data(page, "db.people.find(p=>p.name==='Piotr Zieliński').id")
    drag(side.get_by_role("button", name=re.compile("^Piotr Zieliński")), cell("C725", 1), lambda: on(piotr, "C725", 1))
    check("Rest of the week: offered for Wednesday to Friday after a Tuesday drop", ask.count() == 1 and "Wed to Fri" in ask.inner_text(), ask.inner_text() if ask.count() else "")
    ask.get_by_role("button", name="Yes").click(); page.wait_for_timeout(300)
    check("Rest of the week: Yes plans the free days after it, and not the day before", [on(piotr, "C725", i) for i in range(5)] == [False, True, True, True, True], [on(piotr, "C725", i) for i in range(5)])
    # someone free: place them day by day from the Not placed list
    free_name = "Adrian Stoica"
    pid = data(page, f"db.people.find(p=>p.name==={free_name!r}).id")
    plan = lambda: data(page, f"db.plan.filter(p=>p.personId==='{pid}'&&p.date>='{days[0]}'&&p.date<='{days[4]}').map(p=>[p.projectId,p.date,p.part||'full',p.overtimeHours||0]).sort()")
    side.get_by_role("button", name=re.compile("^" + free_name)).click(); page.wait_for_timeout(250)
    box = page.locator("dialog[open]").first
    check("Person box: a free person has five Free days, each one a button", box.locator("li button", has_text=re.compile("Free")).count() == 5)
    def open_day(i):
        box.locator("li button").nth(i).click(); page.wait_for_timeout(250)
        return page.locator("dialog[open]").last
    dlg = open_day(2)
    check("Day planner: asks which site and offers full day, half day and overtime", dlg.get_by_label("Site").count() == 1 and [t.inner_text() for t in dlg.get_by_role("tab").all()] == ["Full day", "Half day", "Full day + overtime"] and dlg.get_by_role("button", name="Put on site").is_disabled(), dlg.inner_text())
    dlg.get_by_label("Site").select_option("pr-C719"); dlg.get_by_role("tab", name="Half day").click()
    page.screenshot(path=f"{OUT}/90-plan-day.png")
    dlg.get_by_role("button", name="Put on C719").click(); page.wait_for_timeout(300)
    check("Day planner: a half day on Wednesday only is saved, nothing else", plan() == [["pr-C719", days[2], "half", 0]], plan())
    check("Person box: stays open and shows the half day with half the day still free", "C719 half" in box.inner_text() and "half free" in box.inner_text() and box.locator("li button", has_text=re.compile("Free")).count() == 4, box.inner_text())
    check("Week ahead: the grid shows it as a half day", "half day" in chip("C719", 2, free_name).inner_text())
    dlg = open_day(2)
    check("Day planner: reopening the day starts on the site already planned, with Take off", dlg.get_by_label("Site").input_value() == "pr-C719" and dlg.get_by_role("tab", name="Half day").get_attribute("aria-selected") == "true" and dlg.get_by_role("button", name="Take off this day").count() == 1)
    dlg.get_by_label("Site").select_option("pr-C723"); dlg.get_by_role("tab", name="Half day").click(); page.wait_for_timeout(150)
    check("Day planner: a second half day elsewhere is explained as a split day, not a clash", "one full day split across two sites" in dlg.inner_text() and "double books" not in dlg.inner_text(), dlg.inner_text())
    dlg.get_by_role("button", name="Put on C723").click(); page.wait_for_timeout(300)
    check("Week ahead: two half days on two sites raise no double booking", f"{free_name} is on" not in main.inner_text() and len(plan()) == 2, plan())
    dlg = open_day(3)
    dlg.get_by_label("Site").select_option("pr-C719"); dlg.get_by_role("tab", name="Full day + overtime").click()
    ot = dlg.get_by_label("Overtime hours"); ot.click(); ot.press("ControlOrMeta+a"); page.keyboard.type("2.5", delay=40)
    dlg.get_by_role("button", name="Put on C719").click(); page.wait_for_timeout(300)
    check("Day planner: a full day with 2.5 hours overtime is saved and shown", ["pr-C719", days[3], "full", 2.5] in plan() and "+2.5h" in chip("C719", 3, free_name).inner_text(), plan())
    dlg = open_day(2)
    dlg.get_by_label("Site").select_option("pr-C723"); dlg.get_by_role("tab", name="Full day", exact=True).click(); page.wait_for_timeout(150)
    check("Day planner: making one half a full day warns that it double books", "double books" in dlg.inner_text())
    dlg.get_by_role("button", name="Save change").click(); page.wait_for_timeout(300)
    check("Week ahead: a full day plus a half day is flagged as a double booking", f"{free_name} is on" in main.inner_text() and page.get_by_role("button", name="Send the week").is_disabled())
    dlg = open_day(2)
    dlg.get_by_label("Site").select_option("pr-C723"); page.wait_for_timeout(100)
    dlg.get_by_role("button", name="Take off this day").click(); page.wait_for_timeout(300)
    check("Day planner: Take off this day clears just that site and day", f"{free_name} is on" not in main.inner_text() and len(plan()) == 2, plan())
    box.get_by_role("button", name="Close").click(); page.wait_for_timeout(200)
    check("Not placed: he is still listed, with days still free", any(t.startswith(free_name) for t in side.locator("li").all_inner_texts()), side.inner_text())
    # Kevin Shortall cannot work next week (his scaffolding ticket runs out first, Compliance), so another of C719's crew.
    chip("C719", 0, "Marek Wiśniewski").click(); page.wait_for_timeout(250)
    box = page.locator("dialog[open]").first
    dlg = open_day(0)
    dlg.get_by_role("tab", name="Half day").click(); dlg.get_by_role("button", name="Save change").click(); page.wait_for_timeout(300)
    box.get_by_role("button", name="Close").click(); page.wait_for_timeout(200)
    check("Week ahead: a day in the grid can be changed to a half day from the person's box", "half day" in chip("C719", 0, "Marek Wiśniewski").inner_text())
    check("Sample data: one half day is already planned next week (Krzysztof Nowicki, Tuesday)", data(page, "db.plan.filter(p => p.personId==='p-126' && p.part==='half').length") == 1)
    side.get_by_label("Show one trade").select_option(index=1); page.wait_for_timeout(150)
    shown = side.locator("li").all_inner_texts()
    check("Week ahead: the list can be narrowed to one trade", len(shown) >= 1 and len({t.split("\n")[1] for t in shown}) == 1, shown)
    page.set_viewport_size({"width": 1100, "height": 900}); page.wait_for_timeout(250)
    y_side = side.bounding_box()["y"]; y_first = grid.bounding_box()["y"]
    check("Week ahead: on a narrower screen the list sits above the grid", y_side < y_first, (y_side, y_first))
    page.set_viewport_size({"width": 1440, "height": 900})

    # 5. Access: by role and by person
